import{_ as e,o as s,c as t,a6 as n}from"./chunks/framework.De615z8S.js";const u=JSON.parse('{"title":"食品、家居、美妆、3C与服装：品类提示词练习","description":"","frontmatter":{"id":"category-prompts","title":"食品、家居、美妆、3C与服装：品类提示词练习","chapter":"03","status":"已公开","content_kind":"操作教程","evidence_status":"沿原稿品类模板重写；尚未执行图像任务","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":[],"order":24.5},"headers":[],"relativePath":"ecommerce/category-prompts.md","filePath":"ecommerce/category-prompts.md"}'),p={name:"ecommerce/category-prompts.md"};function i(o,a,l,c,r,d){return s(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="食品、家居、美妆、3c与服装-怎样改商品场景词" tabindex="-1">食品、家居、美妆、3C与服装，怎样改商品场景词 <a class="header-anchor" href="#食品、家居、美妆、3c与服装-怎样改商品场景词" aria-label="Permalink to &quot;食品、家居、美妆、3C与服装，怎样改商品场景词&quot;">​</a></h1><p>原稿除了通用套图，还给食品、家居、美妆、3C、服装和科技场景的独立提示词。这篇保留这些任务差异，每种都说明上传什么、复制哪条、结果要检查什么。先使用自己的真实商品照片，生成场景候选；商品保不住时，只生成背景再合成。具体画布和排版操作见<a href="./../start/first-image">第一张图</a>。</p><h2 id="_1-食品-先区分包装与可食部分" tabindex="-1">1. 食品，先区分包装与可食部分 <a class="header-anchor" href="#_1-食品-先区分包装与可食部分" aria-label="Permalink to &quot;1. 食品，先区分包装与可食部分&quot;">​</a></h2><p>准备真实包装、真实食品形态、实际配料和发货清单。包装里的饼干不能生成成另一个口味；配料场景不能让读者误以为实物包含更多水果。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>为上传的食品制作商品页场景副图。商品包装与食品外观分别以提供的真实照片为准，保留包装结构、标签位置、食品颜色和形状。明亮干净餐桌，浅色背景，柔和侧光，少量与实际配料一致的食材放在远处，突出真实食物质感。</span></span>
<span class="line"><span>产品是画面主角，左上留标题区，不生成文字、数字、认证、功效图标或水印。不添加未在配料和发货清单中的食物，不改变份量或口味。包装被改写时只生成空餐桌背景，用真实包装与食品照片合成。</span></span></code></pre></div><p>下载后先核食品颜色、数量、包装标签和配料。保留真实食品的自然纹理，不用“无限拉丝”“爆汁”去强化产品不具备的口感。营养、成分和食品相关声明用实际材料排版。</p><h2 id="_2-家居-检查比例与落地" tabindex="-1">2. 家居，检查比例与落地 <a class="header-anchor" href="#_2-家居-检查比例与落地" aria-label="Permalink to &quot;2. 家居，检查比例与落地&quot;">​</a></h2><p>准备正面/侧面实拍和真实外尺寸。椅子、灯具和家具的场景视角要匹配商品，不从房间效果图推测尺寸。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>为上传的家居商品制作明亮住宅场景副图。商品照片是唯一外观依据，保留形状、颜色、材质、支撑结构、标识和比例。奶油白墙面、浅木地面、柔和自然光，镜头视角接近商品实拍，环境简洁。</span></span>
<span class="line"><span>商品完整展示，底部与地面接触，阴影方向符合窗光；留一处简洁区域用于后期标题。不要把商品拉伸，不增加储物空间或配件，不生成文字、尺寸、认证和水印。透视不匹配时只生成空环境背景。</span></span></code></pre></div><p>看支撑点是否都落地，门、椅背或灯杆有没有被改，室内大小关系是否明显不合理。尺寸图单独做，安装条件与实际使用空间来自测量。</p><h2 id="_3-美妆-标签与瓶体不能靠猜" tabindex="-1">3. 美妆，标签与瓶体不能靠猜 <a class="header-anchor" href="#_3-美妆-标签与瓶体不能靠猜" aria-label="Permalink to &quot;3. 美妆，标签与瓶体不能靠猜&quot;">​</a></h2><p>准备瓶身正面、盖子与标签清晰照片。材质是玻璃、塑料还是金属以事实为准；精华瓶不能被模型改成别的瓶型，场景不暗示无依据的效果。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>为上传的美妆产品制作干净浅色场景图。保留真实瓶型、盖子、泵头、标签位置、容量外观和产品颜色，标识仅以实拍为准。浅色台面、柔和影棚侧光，适度真实反射，少量清水视觉元素作环境，不接触或改变产品包装。</span></span>
<span class="line"><span>竖向构图，上方留标题空间。不生成文字、认证、前后功效对比、医学符号、夸张发光效果或水印，不把塑料做成玻璃，不添加不存在的配件。产品文字被重画时只生成背景并放回真实商品层。</span></span></code></pre></div><p>核盖子与泵头结构、瓶体颜色、包装文字与反射。功效前后对比需要真实合适依据，不能用AI改皮肤来做产品效果证明。</p><h2 id="_4-3c-接口和屏幕来自实物" tabindex="-1">4. 3C，接口和屏幕来自实物 <a class="header-anchor" href="#_4-3c-接口和屏幕来自实物" aria-label="Permalink to &quot;4. 3C，接口和屏幕来自实物&quot;">​</a></h2><p>准备接口、按钮、线缆与发货清单实拍，参数与兼容范围有真实记录。屏幕显示内容单独设计或使用授权素材，不让模型画一组似是而非的参数。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>为上传的3C产品制作简洁桌面场景副图。保持真实外壳、按钮、接口数量与位置、线缆连接方式、颜色和标识。干净办公桌，浅色背景，柔和侧光，少量环境反射，真实商业摄影。</span></span>
<span class="line"><span>商品完整清楚，留白用于后期短标题。不生成文字、参数、认证、虚构接口、附加灯效和水印，不增加不随商品发货的配件，不暗示未确认的兼容设备。无法保留接口时只生成空桌面背景，实物主体后期合成。</span></span></code></pre></div><p>逐个数接口、按钮和线缆，检查孔位有没有被阴影遮掉或补成新孔。功率、速率与协议名称直接从已核实文本排版。</p><h2 id="_5-服装-先保款式再探索展示" tabindex="-1">5. 服装，先保款式再探索展示 <a class="header-anchor" href="#_5-服装-先保款式再探索展示" aria-label="Permalink to &quot;5. 服装，先保款式再探索展示&quot;">​</a></h2><p>准备平铺/挂拍、领口、袖口、纽扣、图案与真实上身照片。工具有专门服装与人物输入时按当前界面使用；没有可核对的服装控制路径，先做静物与场景，不把通用文生图当成真实尺码试穿。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>基于上传的真实服装照片制作服装展示候选。保留领型、袖长、纽扣数量、缝线、图案位置、颜色与面料表现，服装照片是商品依据，获授权人物素材仅作人物参考。</span></span>
<span class="line"><span>自然站姿、简洁浅色环境、柔和光线，服装主要部位无遮挡。不生成文字、Logo和水印，不改版型，不添加口袋或扣件，不改变图案。看不见的背面不补成真实设计。结果只作候选，需与实拍逐项核对，不表示真实尺码适配或穿着效果已验证。</span></span></code></pre></div><p>先数扣件、看花纹，再看人物脸与手。服装生成对了正面不等于背面、垂感和尺寸也对。缺实拍角度就补拍，实际款式与版型展示另核。</p><h2 id="_6-科技氛围图-光效别改商品事实" tabindex="-1">6. 科技氛围图，光效别改商品事实 <a class="header-anchor" href="#_6-科技氛围图-光效别改商品事实" aria-label="Permalink to &quot;6. 科技氛围图，光效别改商品事实&quot;">​</a></h2><p>产品已有品牌方向适合科技场景时，可加入简洁环境光，先控制强度和反射，不把普通商品做成发光装置。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>为上传的真实商品制作科技氛围副图，保留商品形状、接口、按钮、颜色、材质和标识。深浅适中的简洁背景，低强度冷色环境光，柔和边缘照明，主体清晰，真实商业摄影。</span></span>
<span class="line"><span>留出后期标题空间。光效只影响环境，不让产品发出不存在的光，不改变外壳材质，不制造能量线、性能数字、认证、文字和水印。商品必须与原实拍一致，不能用气氛掩盖结构。</span></span></code></pre></div><p>背景气氛变化较大时把真实主体层保留，单独调环境和阴影。若材质变得像镜面或产品颜色被染掉，减弱光效，回实际照片校色。</p><h2 id="_7-改词与返工" tabindex="-1">7. 改词与返工 <a class="header-anchor" href="#_7-改词与返工" aria-label="Permalink to &quot;7. 改词与返工&quot;">​</a></h2><p>先选一类，填自己的素材、用途和画幅，做一个候选，核商品后再延展。每次只改一个可见问题。准确标签、参数和多语言文字在图层或网页文本里处理，生成出来的字也需要逐字复核。以上任务词均未执行本项目生图，不是效果案例。</p>`,28)])])}const b=e(p,[["render",i]]);export{u as __pageData,b as default};
